def pow_mod(a, b, m):
    result = 1
    a = a % m
    while b > 0:
        if b % 2 == 1:
            result = (result * a) % m
        b = b >> 1
        a = (a * a) % m
    return result

def miller_rabin(n, k=5):
    if n < 2:
        return False
    if n == 2 or n == 3:
        return True
    if n % 2 == 0:
        return False

    d = n - 1
    r = 0
    while d % 2 == 0:
        d //= 2
        r += 1

    for _ in range(k):
        a = 2 + (3 * _ % (n - 4))  # a in [2, n-2]
        x = pow_mod(a, d, n)
        if x == 1 or x == n - 1:
