def solution(input_str):
    lines = input_str.strip().split('\n')
    n, m, k, p = map(int, lines[0].split())

    bamboos = []
    for i in range(1, n + 1):
        h, a = map(int, lines[i].split())
        bamboos.append((h, a))

    # Function to check if it's possible to keep all bamboos <= target height
    def check(target):
        if target < 0:
            return False

        total_hits_needed = 0
        for h, a in bamboos:
            final_height = h + a * m  # Height after m days without any hits
            if final_height > target:
                hits_needed = (final_height - target + p - 1) // p  # ceil division
                total_hits_needed += hits_needed

            if total_hits_needed > k * m:
                return False

        return total_hits_needed <= k * m

    # Binary search for the minimum possible maximum height
    # Lower bound: 0, Upper bound: max possible height without any hits
    low = 0
    high = 0
    for h, a in bamboos:
        high = max(high, h + a * m)

    result = high

    while low <= high:
        mid = (low + high) // 2
        if check(mid):
            result = mid
            high = mid - 1
        else:
            low = mid + 1

    return str(result)
