    b = [get_int() for _ in range(n2)]
    c = [get_int() for _ in range(n3)]
    d = [get_int() for _ in range(n4)]

    # Store incompatible pairs as sets for O(1) lookup
    # bad12[y] = set of first course indices incompatible with second course y
    bad12 = {}
    m1 = get_int()
    for _ in range(m1):
        x, y = get_int() - 1, get_int() - 1
        if y not in bad12:
            bad12[y] = set()
        bad12[y].add(x)

    bad23 = {}
    m2 = get_int()
    for _ in range(m2):
        x, y = get_int() - 1, get_int() - 1
        if y not in bad23:
            bad23[y] = set()
        bad23[y].add(x)

    bad34 = {}
    m3 = get_int()
    for _ in range(m3):
        x, y = get_int() - 1, get_int() - 1
        if y not in bad34:
            bad34[y] = set()
        bad34[y].add(x)

    INF = float('inf')

    # Compute dp2: minimum cost to reach each second course
    dp2 = [INF] * n2
    sorted_a = sorted(range(n1), key=lambda i: a[i])

    for j in range(n2):
        found = False
        for i in sorted_a:
            if i not in bad12.get(j, set()):
                dp2[j] = a[i] + b[j]
