            if j not in bad23.get(k, set()):
                dp3[k] = dp2[j] + c[k]
                found = True
                break
        if not found:
            dp3[k] = INF

    if all(x == INF for x in dp3):
        return "-1\n"

    # Compute dp4: minimum cost to reach each dessert
    dp4 = [INF] * n4
    sorted_c = sorted(range(n3), key=lambda k: dp3[k])

    for l in range(n4):
