def solution(input_str):
    lines = input_str.strip().split('\n')
    n, k = map(int, lines[0].split())
    a = list(map(int, lines[1].split()))

    max_val = max(a)

    if k % 2 == 0:
        # For even k: pattern is 0,1,2,0,1,2,... based on n % 3
        x = 0
        for pile in a:
            x ^= (pile % 3)
    else:
        # For odd k: compute Grundy values recursively
        g = [0] * (max_val + 1)

        def get_g(n):
            if g[n] != -1:
                return g[n]

            # Option 1: remove 1 cow -> state n-1
            s = get_g(n - 1)
            seen = {s}

            # Option 2: if n is even, replace with k piles of n/2
            if n % 2 == 0:
                seen.add(get_g(n // 2))  # XOR of k copies (k odd) = g[n//2]

            # Find mex
            m = 0
            while m in seen:
                m += 1
            g[n] = m
            return m

        # Initialize with -1 for uncomputed values
        for i in range(max_val + 1):
            g[i] = -1

        x = 0
        for pile in a:
            x ^= get_g(pile)

    if x != 0:
        return "Kevin\n"
    else:
        return "Nicky\n"
