def is_geometric_progression(arr):
    n = len(arr)
    if n <= 2:
        return True

    # Check if all zeros
    if all(x == 0 for x in arr):
        return True

    # If first element is 0, all must be 0
    if arr[0] == 0 and any(x != 0 for x in arr):
        return False

    # Compute common ratio from first two elements
    # arr[i] = arr[0] * r^i
    # So arr[i] * arr[0] = arr[i+1] * arr[i-1] (cross-product to avoid division)
    # i.e., arr[i+1] * arr[i-1] should equal arr[i]^2

    for i in range(1, n - 1):
        left = arr[i+1] * arr[i-1]
        right = arr[i] * arr[i]
        if left != right:
            return False

    return True


def can_be_geometric_progression_by_deletion(arr):
    n = len(arr)
    if n <= 2:
        return True

    # Try removing each element and check if remaining is a GP
    for i in range(n):
        candidate = arr[:i] + arr[i+1:]
        if is_geometric_progression(candidate):
            return True

    return False
