    for x in arr:
        if x != -1:
            used.add(x)

    available = set()
    for val in range(1, n + 1):
        if val not in used:
            available.add(val)

    positions_neg1 = set()
    for i in range(len(arr)):
        if arr[i] == -1:
            positions_neg1.add(i + 1)

    restrictive = 0
    for pos in positions_neg1:
        if pos in available:
            restrictive += 1

    mod = 1000000007

    combinations = precompute_combinations(m, mod)

    ans = 0
    for j in range(restrictive + 1):
        term = combinations[restrictive][j] * 1 % mod
        for k in range(1, m - j + 1):
            term = term * k % mod

        if j % 2 == 1:
            ans = (ans - term + mod) % mod
        else:
            ans = (ans + term) % mod

    return str(ans)
