        # x = x_or / 100000 (we work with scaled values for ceiling operations)
        new_dp = dp[:]  # Start with values reachable from previous step

        # For each value k reachable at previous step
        for k in range(m + 1):
            if dp[k] == float('inf'):
                continue

            # Try applying operation a times (0 <= a <= y)
            if t == 1:
                # Type 1: k := ceil(k + x)
                # After a applications: ceil(k + a * x) = ceil((k*100000 + a*x_or) / 100000)
                for a in range(y + 1):
