def make_circumcenter_3(p1, p2, p3):
    """Circumcenter of triangle (all points 3D)"""

    # Matrix method: find center equidistant to all 3 points
    # |x-cx|^2 = |y-cx|^2 = |z-cx|^2

    A = [
        [2*(p2[0]-p1[0]), 2*(p2[1]-p1[1]), 2*(p2[2]-p1[2]), 0],
        [2*(p3[0]-p1[0]), 2*(p3[1]-p1[1]), 2*(p3[2]-p1[2]), 0]
    ]
    b = [dist_sq(p2, p1), dist_sq(p3, p1)]
    c = p1[:]

    # Solve Ax = b
    # Use simple Gauss elimination for 3x3 system

    # Form 3x3 or use generalized approach
    d = 2 * (p1[0]*(p2[1]-p3[1]) + p2[0]*(p3[1]-p1[1]) + p3[0]*(p1[1]-p2[1]))

    if abs(d) < 1e-12:
        # Degenerate, return midpoint
        return midpoint(p1, p2)

    x = (   (dist_sq(p1, p1)*(p2[1]-p3[1]) + dist_sq(p2, p2)*(p3[1]-p1[1]) + dist_sq(p3, p3)*(p1[1]-p2[1])) / d
        y = (   (dist_sq(p1, p1)*(p2[2]-p3[2]) + dist_sq(p2, p2)*(p3[2]-p1[2]) + dist_sq(p3, p3)*(p1[2]-p2[2])) / d
        z = (   ((p1[0]*p2[0] + p1[1]*p1[1] + p1[2]*p1[2]) * (p2[1]-p3[1]) + 
                 (p2[0]**2+p2[1]**2+p2[2]**2) * (p3[1]-p1[1]) +
                 (p3[0]**2+p3[1]**2+p3[2]**2) * (p1[1]-p2[1]))  / d)

    return (x, y, z)


def make_circumcenter_4(p1, p2, p3, p4):
    """Circumcenter of tetrahedron"""
    # Solve system: |x-pi|^2 = R^2 for all i
    A = [
        [2*(p2[0]-p1[0]), 2*(p2[1]-p1[1]), 2*(p2[2]-p1[2])],
        [2*(p3[0]-p1[0]), 2*(p3[1]-p1[1]), 2*(p3[2]-p1[2])],
        [2*(p4[0]-p1[0]), 2*(p4[1]-p1[1]), 2*(p4[2]-p1[2])]
    ]
    b = [dist_sq(p2, p1), dist_sq(p3, p1), dist_sq(p4, p1)]

    # Cramers rule or simple elimination
    # For simplicity, use 3x3 solve with elimination
    det = A[0][0]*(A[1][1]*A[2][2] - A[1][2]*A[2][1]) - \
         A[0][1]*(A[1][0]*A[2][2] - A[1][2]*A[2][0]) + \
         A[0][2]*(A[1][0]*A[2][1] - A[1][1]*A[2][0])

    if abs(det) < 1e-12:
        # Coplanar or degenerate, return circumcenter of the plane
        return make_circumcenter_3(p1, p2, p3)

    # Solve for x
    det_x = b[0]*(A[1][1]*A[2][2] - A[1][2]*A[2][1]) - \
            A[0][1]*(b[1]*A[2][2] - A[1][2]*b[2]) + \
            A[0][2]*(b[1]*A[2][1] - A[1][1]*b[2])

    det_y = A[0][0]*(b[1]*A[2][2] - A[1][2]*b[2]) - \
            b[0]*(A[1][0]*A[2][2] - A[1][2]*A[2][0]) + \
            A[0][2]*(A[1][0]*b[2] - b[1]*A[2][0])

    det_z = A[0][0]*(A[1][1]*b[2] - A[1][2]*b[1]) - \
            A[0][1]*(A[1][0]*b[2] - A[1][2]*A[2][0]) + \
            b[0]*(A[1][0]*A[2][1] - A[1][1]*A[2][0])

    x = det_x / det
    y = det_y / det
    z = det_z / det

    return (x, y, z)


