from collections import deque

def solution(input_str):
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())

    # Build adjacency list with edge tracking
    adj = [[] for _ in range(n + 1)]
    edges = set()

    for i in range(1, m + 1):
        u, v = map(int, lines[i].split())
        adj[u].append(v)
        adj[v].append(u)
        edges.add((min(u, v), max(u, v)))

    # Remove bridge edges to see if we can get multiple paths
    # For this problem, we need 3 vertex-disjoint paths (except start/end)
    # This requires finding a cycle where we can route 3 paths

    # Try to find 3 paths between some pair of nodes
    # We'll use BFS/DFS with path constraints

    def find_path(p1, p2, visited, prev_edge, block_set):
        """Find a path from p1 to p2 avoiding block_set edges/vertices"""
        if p1 == p2:
            return []

        visited.add(p1)
        for nxt in adj[p1]:
            if nxt not in visited:
                edge = tuple(sorted((p1, nxt)))
                if edge in block_set:
                    continue
                edge_key = tuple(sorted((p1, nxt)))
                if edge_key in block_set:
                    continue
                res = find_path(nxt, p2, visited.copy(), (edge_key), block_set.copy())
                if res is not None:
                    return [p1] + res
        return None

    def try_find_three_paths(start, end):
        """Try to find 3 paths from start to end that are vertex-disjoint except at endpoints"""
        if start == end:
            return None

        # We need to find 3 internally vertex-disjoint paths
        # First path
        visited1 = {start, end}
        path1 = None
        found = find_path(start, end, visited1, set(), set())
        if path1 is None or found is None:
            return None
        if found:
            path1 = [start] + found

        # Mark internal nodes as blocked for remaining paths
        internal1 = set(path1[1:-1])

        # Second path (avoiding internal nodes of path1)
        visited2 = {start, end}
        path2 = None
        for v in internal1:
