        n, m = map(int, lines[idx].split())
        idx += 1

        matrix = []
        for i in range(n):
            matrix.append(list(map(int, lines[idx].split())))
            idx += 1

        ops = lines[idx]
        idx += 1

        # Apply each operation
        for op in ops:
            if op == 'R':
                # Cyclically shift columns right by 1 for each row
                for i in range(n):
                    row = [0] * n
                    for j in range(n):
                        row[j] = matrix[i][(j - 1) % n]
                    matrix[i] = row
            elif op == 'L':
                # Cyclically shift columns left by 1 for each row
                for i in range(n):
                    row = [0] * n
                    for j in range(n):
                        row[j] = matrix[i][(j + 1) % n]
                    matrix[i] = row
            elif op == 'D':
                # Cyclically shift all rows down by 1
                last = matrix[-1]
                for i in range(n - 1):
                    matrix[i] = matrix[i + 1]
                matrix[-1] = last
            elif op == 'U':
                # Cyclically shift all rows up by 1
                first = matrix[0]
                for i in range(n - 1):
                    matrix[i] = matrix[i + 1]
                matrix[n - 1] = first
            elif op == 'I':
                # Replace each row with its inverse permutation
                for i in range(n):
                    inverse = [0] * n
                    for j in range(n):
                        inverse[matrix[i][j] - 1] = j + 1
                    matrix[i] = inverse
            elif op == 'C':
                # Replace each column with its inverse permutation
                for j in range(n):
                    # Extract column, find inverse, put it back
                    col = [matrix[i][j] for i in range(n)]
                    inverse = [0] * n
                    for i in range(n):
                        inverse[col[i] - 1] = i + 1
                    for i in range(n):
                        matrix[i][j] = inverse[i]

        # Format the output
        result_rows = []
        for row in matrix:
            result_rows.append(' '.join(map(str, row)))
        results.append('\n'.join(result_rows))

    return '\n\n'.join(results)
