Looking at this problem, I need to:
1. Track pairs added by type 1 queries
2. Remove pairs by their query index using type 2 queries
3. For each type 3 query, find max(a*q + b) over all currently active pairs

Since the problem involves maintaining a set with insertions, deletions, and max queries, let me implement this with Python's efficient handling.

```python
def solution(input_str):
    lines = input_str.strip().split('\n')
    n = int(lines[0])

    queries = []
    for i in range(1, n + 1):
        parts = lines[i].split()
        t = int(parts[0])
        if t == 1:
            queries.append((t, int(parts[1]), int(parts[2]), i))
        elif t == 2:
            queries.append((t, int(parts[1]), 0, 0))
        else:
            queries.append((t, int(parts[1]), 0, 0))

    # Store pairs by the query index when they were added
    pairs_by_query_idx = {}
    active_pairs = set()
    result = []

    for i in range(1, n + 1):
        if queries[i-1][0] == 1:
            # Type 1: Add pair (a, b)
            a, b = queries[i-1][1], queries[i-1][2]
            pairs_by_query_idx[i] = (a, b)
            active_pairs.add((a, b))

        elif queries[i-1][0] == 2:
            # Type 2: Remove pair added at query index
            idx_to_remove = queries[i-1][1]
            if idx_to_remove in pairs_by_query_idx:
                pair = pairs_by_query_idx[idx_to_remove]
                del pairs_by_query_idx[idx_to_remove]
                active_pairs.discard(pair)

        else:
            # Type 3: Query max(a*q + b)
            q = queries[i-1][1]
            if not active_pairs:
                result.append("EMPTY SET")
            else:
                max_val = None
                for a, b in active_pairs:
                    val = a * q + b
                    if max_val is None or val > max_val:
                        max_val = val
                result.append(str(max_val))

    return '\n'.join(result)


