Looking at this problem, I need to find a minimum spanning tree with exactly k edges connected to the capital (city 1).

Let me analyze the requirements:
1. Build a connected graph with minimum total edge weight
2. Select exactly k edges that have city 1 as an endpoint
3. Output the number of edges and their indices

This is a constrained MST problem. The approach is to use a modified Kruskal's algorithm:
- Prioritize capital edges up to k count
- After reaching k capital edges, complete the MST with normal (non-capital) edges
- Use Union-Find to track connectivity and avoid cycles

```python
class UnionFind:
    __slots__ = ['parent', 'rank']

    def __init__(self, n):
        self.parent = list(range(n + 1))
        self.rank = [0] * (n + 1)

    def find(self, x):
        root = x
        while self.parent[root] != root:
            root = self.parent[root]
        while self.parent[x] != root:
            nxt = self.parent[x]
            self.parent[x] = root
            x = nxt
        return root

    def union(self, x, y):
        px, py = self.find(x), self.find(y)
        if px == py:
            return False
        if self.rank[px] < self.rank[py]:
            px, py = py, px
        self.parent[py] = px
        if self.rank[px] == self.rank[py]:
            self.rank[px] += 1
        return True


def solution(input_str):
    lines = input_str.strip().split('\n')
    n, m, k = map(int, lines[0].split())

    # Handle edge case: single city
    if n == 1:
        return '0\n\n'

    # Read edges
    edges = []
    for i in range(m):
        parts = lines[i + 1].split()
        a, b, w = int(parts[0]), int(parts[1]), int(parts[2])
        edges.append((w, i + 1, a, b))  # 1-indexed edge index

    # Separate into capital and non-capital edges
    cap_edges = []
    non_cap_edges = []
    for w, idx, a, b in edges:
        if a == 1 or b == 1:
            cap_edges.append((w, idx, a, b))
        else:
            non_cap_edges.append((w, idx, a, b))

    cap_edges.sort()
    non_cap_edges.sort()

    # Count available capital edges
    avail_cap = len(cap_edges)

    # Check feasibility
    if avail_cap < k:
        return '-1\n'

    # Union-Find
    uf = UnionFind(n)
    selected = []
    non_cap_count = 0

    # Try to use up to k capital edges (greedy by weight)
    capital_used = 0
    for w, idx, a, b in cap_edges:
        if capital_used >= k:
            break
        if uf.union(a, b):
            selected.append(idx)
            capital_used += 1

    # If we don't have enough capital edges, we can't satisfy the requirement
    if capital_used < k:
        return '-1\n'
    else:
        # Fill remaining edges with non-capital edges
        while non_cap_count < n - 1 - len([e for e in selected if e[1] >= 1 and any(a==e or b==e for a,b,_,_ in [cap_edges[:capital_used]])]):
            pass

        for w, idx, a, b in non_cap_edges:
            if uf.union(a, b):
                selected.append(idx)
                non_cap_count += 1

    # Check if we have exactly n-1 edges (MST condition)
    if len(selected) != n - 1:
        return '-1\n'

    # Check connectivity (should be satisfied if we have n-1 edges and no cycles)
    root = uf.find(1)
    for i in range(2, n + 1):
        if uf.find(i) != root:
            return '-1\n'

    # Sort by original index and format output
    selected.sort()
    return f"{n - 1}\n{' '.join(map(str, selected))}\n"


