Looking at this problem, I need to count squares in a 0-1 matrix. There are two types:
1. **Axis-aligned squares**: Borders (frame) are aligned with the matrix axes, interior must be all 0s
2. **Diagonal squares**: Frame follows 45° diagonals (diamond shape), interior must be all 0s

Key constraint: No "foreign" 1 can touch the square frame by side or corner.

```python
def solution(input_data):
    """
    Counts the number of squares (both axis-aligned and diagonal) in a 0-1 matrix.
    A square must be a solid frame with linewidth 1, at least 2×2, and cannot touch
    any foreign 1 by side or corner.
    """
    lines = input_data.strip().split('\n')
    idx = 0

    t = int(lines[idx])
    idx += 1
    results = []

    for _ in range(t):
        n, m = map(int, lines[idx].split())
        idx += 1
        matrix = []
        for i in range(n):
            matrix.append(list(lines[idx]))
            idx += 1

        count = 0

        # Check axis-aligned squares
        for size in range(2, min(n, m) + 1):
            for r in range(n - size + 1):
                for c in range(m - size + 1):
                    if check_axis_square(matrix, r, c, size):
                        count += 1

        # Check diagonal squares
        for center_r in range(n):
            for center_c in range(m):
                # Try all possible radii (diameter should be at least 2)
                for radius in range(1, min(n, m) // 2 + 2):
                    if check_diag_square(matrix, center_r, center_c, radius):
                        count += 1

        results.append(str(count))

    return '\n'.join(results)


def check_axis_square(matrix, r, c, size):
    """
    Check if an axis-aligned square of given size exists with top-left at (r, c).
    - Frame (borders) must all be 1
    - Interior must all be 0
    - No foreign 1 can touch the frame (8-directionally)
    """
    n, m = len(matrix), len(matrix[0])

    if size < 2:
        return False

    # Check all 4 borders are 1
    for i in range(size):
        if matrix[r][c + i] != '1' or matrix[r + size - 1][c + i] != '1':
            return False
        if matrix[r + i][c] != '1' or matrix[r + i][c + size - 1] != '1':
            return False

    # Interior must be all 0
    for i in range(1, size - 1):
        for j in range(1, size - 1):
            if matrix[r + i][c + j] != '0':
                return False

    # No foreign 1s can touch the frame (8-direction check)
    for i in range(r - 1, r + size):
        for j in range(c - 1, c + size):
            # Check cells that are outside the frame
            if not (r <= i < r + size and c <= j < c + size):
                if 0 <= i < n and 0 <= j < m:
                    if matrix[i][j] == '1':
                        return False

    return True


def check_diag_square(matrix, center_r, center_c, radius):
    """
    Check if a diagonal square (diamond) with given radius exists at given center.
    - Frame: cells with Manhattan distance == radius from center must be 1
    - Interior: cells with Manhattan distance < radius must be 0
    - Outside: cells with Manhattan distance > radius must be 0 (no touching foreign 1s)

    This approach ensures the frame is isolated from any foreign 1s.
    """
    n, m = len(matrix), len(matrix[0])

    # Check all relevant cells from -radius-1 to radius+1
    for i in range(-radius - 1, radius + 2):
        for j in range(-radius - 1, radius + 2):
            dist = abs(i) + abs(j)
            nr, nc = center_r + i, center_c + j

            if 0 <= nr < n and 0 <= nc < m:
                if dist == radius:
                    # Frame must be 1
                    if matrix[nr][nc] != '1':
                        return False
                elif dist > radius:
                    # Outside cells cannot be 1 (no touching foreign 1s)
                    if matrix[nr][nc] == '1':
                        return False
                # dist < radius: interior, must be 0
                if matrix[nr][nc] != '0':
                    return False

    return True


