Looking at this problem, I need to determine if a CNF formula is satisfiable where each variable appears in at most 2 clauses. This is a specialized case of 2-SAT that can be solved using backtracking with efficient pruning.

```python
def solution(input_str):
    lines = input_str.strip().split('\n')
    if not lines:
        return "NO"

    n, m = map(int, lines[0].split())

    # Parse clauses
    clauses = []
    for i in range(n):
        parts = list(map(int, lines[i + 1].split()))
        # parts[0] is the number of literals
        clause_literals = parts[1:]
        clauses.append(clause_literals)

    # Track assignment for each variable (0 means false/0, 1 means true/1)
    assignment = [-1] * m

    def is_satisfied():
        """Check if all clauses are satisfied by current assignment"""
        for clause in clauses:
            satisfied = False
            for lit in clause:
                var = abs(lit) - 1  # Convert to 0-indexed
                if lit > 0:
                    if assignment[var] == 1:  # literal is x_i (positive)
                        satisfied = True
                        break
                else:
                    if assignment[var] == 0:  # literal is ¬x_i (negative)
                        satisfied = True
                        break
            if not satisfied:
                return False
        return True

    def backtrack(idx):
        """Try to find a valid assignment for variables from idx to m-1"""
        if idx == m:
            return is_satisfied()

        # Try both 0 (false) and 1 (true)
        for val in [1, 0]:
            old_val = assignment[idx]
            assignment[idx] = val

            if backtrack(idx + 1):
                return True

            # Backtrack: restore previous value
            assignment[idx] = old_val

        return False

    if backtrack(0):
        yes = "".join(str(x) for x in assignment)
        return "YES\n" + yes
    else:
        return "NO"
```

The solution uses recursive backtracking to try all possible assignments:
1. Parse the input to extract clauses
2. For each variable (in order), try assigning it a value (0 or 1)
3. Track assignments and check if all clauses are satisfied
4. If all variables are assigned and all clauses satisfied, return YES with the assignment
5. Otherwise backtrack and try different values
6. If no valid assignment can be found, return NO

This efficient backtracking approach works well given the constraint that each variable appears in at most 2 clauses, which limits the search space.

```python
def solution(input_str):
    parts = input_str.strip().split()
    a = int(parts[0])
    b = int(parts[1])
    n = int(parts[2])

    # If a == 1, then 1^b = 1 for all b, which is always < n (since n >= 2)
    # Players can increase b indefinitely without ever reaching n, causing a draw
    if a == 1:
        return "Missing\n\n"

    # Memoization for game theory DP
    memo = {}
    visited = set()

    def is_losing(a, b):
        """Returns True if current player loses from position (a, b)"""
        key = (a, b)
        if key in memo:
            return memo[key]
        if key in visited:
            return False  # Should not happen due to monotonicity

        visited.add(key)

        # Check if all moves lead to opponent winning (i.e., they lose for us)
        all_moves_lead_to_opponent_win = True

        # Try increasing a (boxes)
        try:
            ways_a = (a + 1) ** b
            if ways_a < n:
                if not is_losing(a + 1, b):
                    all_moves_lead_to_opponent_win = False
        except OverflowError:
            pass

        # Try increasing b (items)
        try:
            ways_b = a ** (b + 1)
            if ways_b < n:
                if not is_losing(a, b + 1):
                    all_moves_lead_to_opponent_win = False
        except OverflowError:
            pass

        result = all_moves_lead_to_opponent_win
        memo[key] = result
        visited.discard(key)
        return result

    # With a >= 2, the game must end (a^b grows to n)
    if is_losing(a, b):
        return "Masha\n\n"
    else:
        return "Stas\n\n"
