                partner_of[j] = idx + 1

                if backtrack(idx + 1):
                    return True

                partner_of[idx] = 0
                partner_of[j] = 0

        return False

    if backtrack(0):
        return "\n".join(str(x) for x in partner_of) + "\n"
    return "-1\n"
